// Package wal reads the palette generated by pywal so the keyboard can follow
// the desktop colors.
package wal

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// Palette is the subset of pywal output openaula cares about.
type Palette struct {
	Colors     [16][3]uint8
	Background [3]uint8
	Foreground [3]uint8
	Path       string
}

type colorsJSON struct {
	Special struct {
		Background string `json:"background"`
		Foreground string `json:"foreground"`
		Cursor     string `json:"cursor"`
	} `json:"special"`
	Colors map[string]string `json:"colors"`
	// wallust writes the colorN keys at the top level.
	Color0      string `json:"color0"`
	Color1      string `json:"color1"`
	Color2      string `json:"color2"`
	Color3      string `json:"color3"`
	Color4      string `json:"color4"`
	Color5      string `json:"color5"`
	Color6      string `json:"color6"`
	Color7      string `json:"color7"`
	Color8      string `json:"color8"`
	Color9      string `json:"color9"`
	Color10     string `json:"color10"`
	Color11     string `json:"color11"`
	Color12     string `json:"color12"`
	Color13     string `json:"color13"`
	Color14     string `json:"color14"`
	Color15     string `json:"color15"`
	Background2 string `json:"background"`
	Foreground2 string `json:"foreground"`
}

// Dir returns the pywal cache directory.
func Dir() (string, error) {
	if base := os.Getenv("XDG_CACHE_HOME"); base != "" {
		return filepath.Join(base, "wal"), nil
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(home, ".cache", "wal"), nil
}

// Load reads the current pywal or wallust palette.
func Load() (Palette, error) {
	dir, err := Dir()
	if err != nil {
		return Palette{}, err
	}
	candidates := []string{
		filepath.Join(dir, "colors.json"),
		filepath.Join(filepath.Dir(dir), "wallust", "colors.json"),
	}
	for _, path := range candidates {
		if data, err := os.ReadFile(path); err == nil {
			if p, err := parseJSON(path, data); err == nil {
				return p, nil
			}
		}
	}
	// Fallback: plain "colors" file, one hex per line.
	plainPath := filepath.Join(dir, "colors")
	data, err := os.ReadFile(plainPath)
	if err != nil {
		return Palette{}, fmt.Errorf("no encontré la paleta de pywal/wallust en %s (¿corriste wal?)", dir)
	}
	return parsePlain(plainPath, string(data))
}

func parseJSON(path string, data []byte) (Palette, error) {
	var c colorsJSON
	if err := json.Unmarshal(data, &c); err != nil {
		return Palette{}, fmt.Errorf("parseando %s: %w", path, err)
	}
	p := Palette{Path: path}
	for i := 0; i < 16; i++ {
		key := fmt.Sprintf("color%d", i)
		if v, ok := c.Colors[key]; ok {
			if rgb, err := ParseHex(v); err == nil {
				p.Colors[i] = rgb
			}
		}
	}
	if c.Special.Background != "" {
		p.Background, _ = ParseHex(c.Special.Background)
	} else {
		p.Background, _ = ParseHex(c.Background2)
	}
	if c.Special.Foreground != "" {
		p.Foreground, _ = ParseHex(c.Special.Foreground)
	} else {
		p.Foreground, _ = ParseHex(c.Foreground2)
	}
	// wallust schema: top-level colorN.
	top := []string{c.Color0, c.Color1, c.Color2, c.Color3, c.Color4, c.Color5, c.Color6, c.Color7,
		c.Color8, c.Color9, c.Color10, c.Color11, c.Color12, c.Color13, c.Color14, c.Color15}
	for i, v := range top {
		if v != "" && p.Colors[i] == [3]uint8{} {
			if rgb, err := ParseHex(v); err == nil {
				p.Colors[i] = rgb
			}
		}
	}
	return p, nil
}

func parsePlain(path, data string) (Palette, error) {
	p := Palette{Path: path}
	lines := strings.Split(strings.TrimSpace(data), "\n")
	for i := 0; i < len(lines) && i < 16; i++ {
		if rgb, err := ParseHex(lines[i]); err == nil {
			p.Colors[i] = rgb
		}
	}
	return p, nil
}

// ParseHex accepts "#rrggbb" or "rrggbb".
func ParseHex(s string) ([3]uint8, error) {
	s = strings.TrimPrefix(strings.TrimSpace(s), "#")
	if len(s) != 6 {
		return [3]uint8{}, fmt.Errorf("color hex inválido %q", s)
	}
	var out [3]uint8
	for i := 0; i < 3; i++ {
		var v int
		if _, err := fmt.Sscanf(s[i*2:i*2+2], "%02x", &v); err != nil {
			return out, fmt.Errorf("color hex inválido %q", s)
		}
		out[i] = uint8(v)
	}
	return out, nil
}

// Accent returns one of the 16 colors, clamped to range.
func (p Palette) Accent(index int) [3]uint8 {
	if index < 0 || index > 15 {
		index = 4
	}
	return p.Colors[index]
}
